<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Controllers\Api\V1\Concerns\ApiResponse; use App\Http\Requests\Api\V1\Chest\OpenChestRequest; use App\Http\Resources\Api\V1\{UserChestResource,UserCollectibleResource}; use App\Models\UserChest; use App\Services\Game\ChestService; use Illuminate\Http\Request; use Throwable; class ChestController extends Controller{use ApiResponse; public function index(Request $r){$q=$r->user()->userChests()->with('chest'); if($r->filled('status')){$q->where('status',$r->query('status'));} return $this->success('Coffres utilisateur.', UserChestResource::collection($q->latest()->get()));} public function open(OpenChestRequest $r, UserChest $userChest, ChestService $svc){try{$rewards=$svc->openChest($r->user(),$userChest); if($rewards['collectible']){$rewards['collectible']=new UserCollectibleResource($rewards['collectible']->load('collectible'));} return $this->success('Coffre ouvert.',$rewards);}catch(Throwable $e){return $this->businessError($e,'open chest failed');}}}
